    const title = (match.title || match.link?.getAttribute('title') || match.link?.textContent?.trim() ||
      titleLink?.getAttribute('title') || titleLink?.textContent || innerImage?.getAttribute('alt') || cover.getAttribute('title') || '').replace(/\s+/g,' ').trim().slice(0, 70) || `작품 #${match.id}`;
