  document.addEventListener('pointerover', beginHover, true);
  // 인기작품 섹션은 페이지 로딩 후 생성될 수 있어 첫 이용 전에 목록을 준비한다.
  setTimeout(()=>{if(document.querySelector('.hot-rank-card'))loadHotCoverIndex();},1300);
