      const panel=document.createElement('div');
      panel.style.cssText='position:fixed;inset:16px;z-index:2147483647;background:#161827;color:white;padding:18px;border-radius:16px;display:flex;flex-direction:column;gap:10px;font:14px system-ui';
      const heading=document.createElement('strong');heading.textContent='표지 진단 결과 · 서버 전송 없음';
      const area=document.createElement('textarea');area.readOnly=true;area.value=output;
      area.style.cssText='flex:1;min-height:180px;background:#10111b;color:#eee;border:1px solid #667;border-radius:8px';
      const actions=document.createElement('div');
      const copy=document.createElement('button');copy.textContent='결과 복사';
      const close=document.createElement('button');close.textContent='닫기';
