  window.__novelpiaIndicatorDebug = Object.freeze({version: VERSION, jobs, analyze, scoreToGrade, stabilityAnalysis, parseRows, parseNovelMetadata, publishedCountFromDoc, identifyCover, readNovelId, findNovel, episodeIdentity, normalizedEpisodes, rawRowsComplete, allChaptersCollected, loadCheckpoint, clearCheckpoint, mergeEvents, extractNovelMeta, loadHotCoverIndex, coverKey, showNovel, commitCoverNavigation, rememberedCoverMatch, findUniqueTileNovel});
